/**
 * Small JSON client for fixture setup (the load itself is generated by autocannon) and the login
 * flow the app uses: password login, plus the new-device OTP step when the API asks for it.
 */
import fs from 'node:fs';
import readline from 'node:readline/promises';
import { API_URL, settings } from './env';

export class ApiError extends Error {
  constructor(
    readonly status: number,
    readonly body: unknown,
    message: string,
  ) {
    super(message);
  }
}

type Method = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';

/** Sends a request to `/api${path}`; JSON bodies by default, FormData as multipart. Throws unless 2xx. */
export async function call<T>(
  method: Method,
  path: string,
  options: { token?: string; body?: unknown } = {},
): Promise<T> {
  const headers: Record<string, string> = {};
  if (options.token) headers.authorization = `Bearer ${options.token}`;
  let body: string | FormData | undefined;
  if (options.body instanceof FormData) body = options.body;
  else if (options.body !== undefined) {
    headers['content-type'] = 'application/json';
    body = JSON.stringify(options.body);
  }
  const response = await fetch(`${API_URL}/api${path}`, { method, headers, body });
  const text = await response.text();
  let parsed: unknown = text;
  try {
    parsed = text ? JSON.parse(text) : null;
  } catch {
    // not JSON
  }
  if (!response.ok)
    throw new ApiError(
      response.status,
      parsed,
      `${method} ${path} → ${response.status} ${text.slice(0, 300)}`,
    );
  return parsed as T;
}

export interface Device {
  uid: string;
  name: string;
  platform: 'web';
}

type LoginResponse =
  | { status: 'authenticated'; accessToken: string; refreshToken: string }
  | { status: 'otp_required'; challengeId: string }
  | { status: 'device_limit_reached'; maxDevices: number };

function outboxSize(): number {
  try {
    return fs.statSync(settings.outboxFile).size;
  } catch {
    return 0;
  }
}

/** Waits for the OTP sent to `mobile` after byte offset `since` of the API's DEV_OUTBOX_FILE. */
async function otpFromOutbox(mobile: string, since: number): Promise<string | undefined> {
  const deadline = Date.now() + 15_000;
  while (Date.now() < deadline) {
    try {
      const text = fs.readFileSync(settings.outboxFile).subarray(since).toString('utf8');
      const otp = text
        .split('\n')
        .filter(Boolean)
        .map((line) => {
          try {
            return JSON.parse(line) as { to?: string; data?: { otp?: unknown } };
          } catch {
            return {};
          }
        })
        .reverse()
        .find((m) => m.to === mobile && typeof m.data?.otp === 'string')?.data?.otp;
      if (typeof otp === 'string') return otp;
    } catch {
      // the file appears with the first message
    }
    await new Promise((resolve) => setTimeout(resolve, 250));
  }
  return undefined;
}

async function readOtp(mobile: string, since: number): Promise<string> {
  if (fs.existsSync(settings.outboxFile)) {
    const otp = await otpFromOutbox(mobile, since);
    if (otp) return otp;
  }
  if (process.stdin.isTTY) {
    const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
    try {
      return (await rl.question(`OTP sent to ${mobile} (printed in the API log): `)).trim();
    } finally {
      rl.close();
    }
  }
  throw new Error(
    `${mobile} needs a new-device OTP and none was found in ${settings.outboxFile}. Start the API with ` +
      '`npm run load:serve` (it writes that outbox), set LOAD_OUTBOX_FILE to the API’s DEV_OUTBOX_FILE, ' +
      'run interactively to type the OTP, or pass LOAD_SUPERADMIN_TOKEN.',
  );
}

/** Password login on a fixed device; returns an access token. Known devices skip the OTP step. */
export async function passwordLogin(mobile: string, password: string, device: Device): Promise<string> {
  const since = outboxSize();
  let result = await call<LoginResponse>('POST', '/auth/login', {
    body: { identifier: mobile, password, device },
  });
  if (result.status === 'otp_required') {
    const code = await readOtp(mobile, since);
    result = await call<LoginResponse>('POST', '/auth/otp/verify', {
      body: { challengeId: result.challengeId, code, device },
    });
  }
  if (result.status === 'device_limit_reached')
    throw new Error(
      `${mobile} already has ${result.maxDevices} active devices. Sign one out, or pass LOAD_SUPERADMIN_TOKEN.`,
    );
  if (result.status !== 'authenticated') throw new Error(`Login for ${mobile} did not complete`);
  return result.accessToken;
}
